//! KDE Theme Profile Manager - Rust Core Library
//!
//! Provides native Rust implementation of the theme management protocol
//! with FFI interface for Python integration.
//!
//! The FFI layer is deliberately thin: every `kde_theme_core_*` entry point is
//! generated by one of the `ffi_*!` macros below, which turn a `Result`-based
//! body into the C ABI (JSON/plain-text `*mut c_char` or `c_int` status) and
//! record the last failure in `LAST_ERROR` (`kde_theme_core_get_error`).

#![allow(non_snake_case)]

pub mod types;
pub mod paths;
pub mod profile;
pub mod wallpaper;
pub mod tracked_apps;
pub mod settings;
pub mod config_parser;
pub mod status;

use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int};
use std::ptr;
use std::sync::Mutex;

use tracing::info;

