pub use tracked_apps::TrackedAppsCore;
pub use settings::SettingsCore;

// Global error message storage for FFI
static LAST_ERROR: Mutex<Option<String>> = Mutex::new(None);

fn set_last_error(err: String) {
    if let Ok(mut guard) = LAST_ERROR.lock() {
        *guard = Some(err);
    }
}

fn take_last_error() -> Option<String> {
    if let Ok(mut guard) = LAST_ERROR.lock() {
        guard.take()
    } else {
        None
    }
}

/// Read a borrowed C string argument without dereferencing NULL.
fn read_cstr(ptr: *const c_char, name: &str) -> Result<String, String> {
    if ptr.is_null() {
        return Err(format!("{name} is null"));
    }
    unsafe { CStr::from_ptr(ptr) }
        .to_str()
        .map(str::to_owned)
        .map_err(|e| e.to_string())
}

// ─────────────────────────────────────────────────────────────────────────────
// FFI macros
//
// Each macro runs its body in a closure that may use `?`, then converts the
// result to the C ABI. A body returns `anyhow::Result<…>`.
// ─────────────────────────────────────────────────────────────────────────────

/// `*mut c_char` output: the Ok `String` is handed to C as-is.
macro_rules! ffi_cstr {
    ($name:ident($($arg:ident: $ty:ty),*) => $body:block) => {
        #[no_mangle]
        #[allow(clippy::redundant_closure_call)]
        pub extern "C" fn $name($($arg: $ty),*) -> *mut c_char {
            let result = (|| -> anyhow::Result<String> { $body })();
            match result {
                Ok(text) => match CString::new(text) {
                    Ok(c) => c.into_raw(),
                    Err(e) => { set_last_error(e.to_string()); ptr::null_mut() }
                },
                Err(e) => { set_last_error(format!("{e:#}")); ptr::null_mut() }
            }
        }
    };
}

/// `*mut c_char` output: the Ok value is JSON-serialised first.
macro_rules! ffi_json {
    ($name:ident($($arg:ident: $ty:ty),*) => $body:block) => {
        #[no_mangle]
        #[allow(clippy::redundant_closure_call)]
        pub extern "C" fn $name($($arg: $ty),*) -> *mut c_char {
            let result = (|| -> anyhow::Result<serde_json::Value> { $body })();
            let json = match result.and_then(|v| serde_json::to_string(&v).map_err(anyhow::Error::from)) {
                Ok(s) => s,
                Err(e) => { set_last_error(format!("{e:#}")); return ptr::null_mut(); }
            };
            match CString::new(json) {
                Ok(c) => c.into_raw(),
                Err(e) => { set_last_error(e.to_string()); ptr::null_mut() }
            }
        }
    };
}

/// `c_int` status output: 0 on success, -1 with the recorded error otherwise.
macro_rules! ffi_status {
    ($name:ident($($arg:ident: $ty:ty),*) => $body:block) => {
        #[no_mangle]
        #[allow(clippy::redundant_closure_call)]
        pub extern "C" fn $name($($arg: $ty),*) -> c_int {
            let result = (|| -> anyhow::Result<()> { $body })();
            match result {
                Ok(()) => 0,
                Err(e) => { set_last_error(format!("{e:#}")); -1 }
            }
        }
    };
}

/// Parse the optional `--components` JSON argument (`NULL` → all components).
fn parse_optional_components(ptr: *const c_char) -> anyhow::Result<Option<Vec<String>>> {
    if ptr.is_null() {
        return Ok(None);
    }
    let json = read_cstr(ptr, "components_json").map_err(anyhow::Error::msg)?;
    Ok(Some(serde_json::from_str(&json)?))
}

// ─────────────────────────────────────────────────────────────────────────────
// Library lifecycle
// ─────────────────────────────────────────────────────────────────────────────

/// Initialize the Rust core library
#[no_mangle]
pub extern "C" fn kde_theme_core_init() -> c_int {
    // Initialize tracing subscriber for logging
    let _ = tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .try_init();

    info!("KDE Theme Core initialized");
    0 // Success
}

/// Get the last error message
#[no_mangle]
pub extern "C" fn kde_theme_core_get_error() -> *const c_char {
    if let Some(err) = take_last_error() {
        match CString::new(err) {
            Ok(c_str) => c_str.into_raw(),
            Err(_) => ptr::null(),
        }
    } else {
        ptr::null()
    }
}

/// Free a string returned by FFI functions
#[allow(clippy::not_unsafe_ptr_arg_deref)]
#[no_mangle]
pub extern "C" fn kde_theme_core_free_string(ptr: *mut c_char) {
    if !ptr.is_null() {
        unsafe {
            drop(CString::from_raw(ptr));
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Profile Core
// ─────────────────────────────────────────────────────────────────────────────

ffi_json!(kde_theme_core_profile_list() => {
    Ok(serde_json::to_value(profile::list_profiles()?)?)
});

ffi_cstr!(kde_theme_core_profile_get_active() => {
    profile::get_active_profile()
});

ffi_status!(kde_theme_core_profile_apply(
    profile_name: *const c_char,
    components_json: *const c_char
) => {
    let name = read_cstr(profile_name, "profile_name").map_err(anyhow::Error::msg)?;
    let components = parse_optional_components(components_json)?;
    profile::apply_profile_impl(&name, components)?;
    Ok(())
});

ffi_status!(kde_theme_core_profile_save(
    profile_name: *const c_char,
    components_json: *const c_char
) => {
    let name = read_cstr(profile_name, "profile_name").map_err(anyhow::Error::msg)?;
    let components = parse_optional_components(components_json)?;
    profile::save_profile_impl(&name, components)?;
    Ok(())
});

ffi_status!(kde_theme_core_profile_delete(profile_name: *const c_char) => {
    let name = read_cstr(profile_name, "profile_name").map_err(anyhow::Error::msg)?;
    profile::delete_profile(&name)?;
    Ok(())
});

ffi_cstr!(kde_theme_core_profile_diff(
    profile_a: *const c_char,
    profile_b: *const c_char
) => {
    let a = read_cstr(profile_a, "profile_a").map_err(anyhow::Error::msg)?;
    let b = read_cstr(profile_b, "profile_b").map_err(anyhow::Error::msg)?;
    profile::diff_profiles(&a, &b)
});

ffi_json!(kde_theme_core_profile_get_components(profile_name: *const c_char) => {
    let name = read_cstr(profile_name, "profile_name").map_err(anyhow::Error::msg)?;
    Ok(serde_json::to_value(profile::get_profile_components(&name)?)?)
});

