/// Override the wallpaper listing directory. The application reads
/// `wallpaper_directory` from its settings; the Rust core has to be told about
/// it explicitly (empty string resets to the default).
#[no_mangle]
pub extern "C" fn kde_theme_core_wallpaper_set_dir(dir: *const c_char) -> c_int {
    if dir.is_null() {
        wallpaper::set_wallpaper_dir("");
        return 0;
    }
    match read_cstr(dir, "dir") {
        Ok(s) => {
            wallpaper::set_wallpaper_dir(&s);
            0
        }
        Err(e) => {
            set_last_error(e);
            -1
        }
    }
}

